from collections import Counter, deque

def bg_color(grid):
    """The most common color in the grid (the background)."""
    return Counter(v for r in grid for v in r).most_common(1)[0][0]

def components(grid, color=None):
    """4-connected components of cells != background (or == color); list of cell sets."""
    h,w=len(grid),len(grid[0]); b=bg_color(grid); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=b and (i,j) not in seen:
                comp=set(); q=deque([(i,j)]); seen.add((i,j))
                while q:
                    a,b2=q.popleft(); comp.add((a,b2))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b2+db
                        if 0<=na<h and 0<=nb<w and grid[na][nb]!=b and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                out.append(comp)
    return out

def rect_frames(grid):
    """Closed rectangle outlines: (color, top, left, bottom, right) for each non-bg component forming a full frame."""
    out=[]
    for comp in components(grid):
        cs={grid[a][b] for a,b in comp}
        if len(cs)!=1: continue
        c=next(iter(cs))
        i=min(a for a,b in comp); j=min(b for a,b in comp)
        i2=max(a for a,b in comp); j2=max(b for a,b in comp)
        if i2-i<2 or j2-j<2: continue
        border={(a,b) for a in range(i,i2+1) for b in range(j,j2+1)
                if a in (i,i2) or b in (j,j2)}
        if comp==border:
            out.append((c,i,j,i2,j2))
    return out

def fill_rect_interiors(grid, odd_fill, even_fill):
    """Fill each closed rectangle outline's interior: odd interior side -> odd_fill, even -> even_fill."""
    g=[r[:] for r in grid]
    for c,i,j,i2,j2 in rect_frames(grid):
        f = odd_fill if (i2-i-1)%2==1 else even_fill
        for a in range(i+1,i2):
            for b in range(j+1,j2):
                g[a][b]=f
    return g

def transform(grid):
    return fill_rect_interiors(grid, 7, 2)

